#include "stdlib/lapack/base/dla_porpvgrw.h"
#include <stdio.h>

int main( void ) {
	const double A[] = { 0.25, 0.0, 0.0, 4.0 };
	const double AF[] = { 0.5, 0.0, 0.0, 2.0 };
	double WORK[ 4 ];
	double value;
	LAPACK_INT i;

	value = API_SUFFIX(c_dla_porpvgrw)( LAPACK_ROW_MAJOR, LAPACK_UPPER_TRIANGLE, 2, A, 2, AF, 2, WORK );
	printf( "reciprocal pivot growth: %g\n", value );
	for ( i = 0; i < 4; i++ ) {
		printf( "WORK[%" LAPACK_IFMT "]: %g\n", i, WORK[ i ] );
	}
	return value != 0.5;
}
